
import React from 'react';
import Navbar from '@/components/Navbar';
import { motion } from 'framer-motion';
export default function TradingPage() {
    return (
        <main className="min-h-screen bg-[#92CDE1] w-full  relative overflow-hidden">
            <Navbar />
            <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8 }}
            className="relative h-screen w-full flex flex-col-2"
            >
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-black/30 z-10"></div>
            <img 
              src="/images/trading.png" 
              alt="Marine Services"
              className="w-full h-full object-cover"
            />
            </motion.div>
        </main>
    );
}
